SourceCode.Declaration:
/// <summary>
/// Extension of <c>ProdJournalTable</c> to trigger pick list posted and route card posted business events.
/// </summary>
[ExtensionOf(tableStr(ProdJournalTable))]
final class AAXProdJournalTable_Table_Extension
{
}

Method.Source:
/// <summary>
/// Triggers pick list or route card posted business events when a production journal is posted.
/// </summary>
void update()
{
    boolean wasNotPosted = (this.orig().Posted == NoYes::No);

    next update();

    if (wasNotPosted && this.Posted == NoYes::Yes)
    {
        ProdTable prodTable = ProdTable::find(this.ProdId);

        if (this.JournalType == ProdJournalType::Picklist)
        {
            if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXProdPickListPostedBusinessEvent)))
            {
                ProdJournalBOM prodJournalBOM;
                select sum(BOMConsump) from prodJournalBOM
                    where prodJournalBOM.JournalId == this.JournalId;

                AAXProdPickListPostedBusinessEvent::newFromProdTable(prodTable, prodJournalBOM.BOMConsump, 0).send();
            }
        }
        else if (this.JournalType == ProdJournalType::RouteCard)
        {
            if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXProdRouteCardPostedBusinessEvent)))
            {
                ProdJournalRoute prodJournalRoute;
                select sum(QtyGood), sum(QtyError) from prodJournalRoute
                    where prodJournalRoute.JournalId == this.JournalId;

                AAXProdRouteCardPostedBusinessEvent::newFromProdTable(prodTable, prodJournalRoute.QtyGood, prodJournalRoute.QtyError).send();
            }
        }
    }
}
